@push('scripts')<script>document.addEventListener('DOMContentLoaded',()=>{const form=document.getElementById('assistantForm');const input=document.getElementById('chatQuestion');const feed=document.getElementById('chatMessages');const btn=document.getElementById('sendButton');function add(text,cls){const el=document.createElement('div');el.className='chat-bubble '+cls;el.textContent=text;feed.append(el);feed.scrollTop=feed.scrollHeight;return el;}form.addEventListener('submit',async e=>{e.preventDefault();const question=input.value.trim();if(!question||btn.disabled)return;add(question,'user');input.value='';btn.disabled=true;const wait=add('جاري قراءة البيانات المحلية...','bot');try{const res=await fetch(@json(route('assistant.ask')),{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content},body:JSON.stringify({question}),credentials:'same-origin'});const data=await res.json();wait.textContent=res.ok?(data.answer||'لا توجد إجابة'):(data.message||'تعذر إتمام الطلب.');}catch(err){wait.textContent='تعذر الاتصال بالخادم المحلي. تحقق من اتصالك بخادم Laravel.';}finally{btn.disabled=false;input.focus();feed.scrollTop=feed.scrollHeight;}});document.querySelectorAll('[data-question]').forEach(b=>b.addEventListener('click',()=>{input.value=b.dataset.question;form.requestSubmit();}));feed.scrollTop=feed.scrollHeight;});</script>@endpush
